#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 '--description=firewall 2'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 '--description=firewall 2'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.168.127.200/29,192.168.127.208/28,192.168.127.224/28,192.168.127.240/29,192.168.127.248/31,192.168.127.250/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=firewall 9'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.168.127.200/29,192.168.127.208/28,192.168.127.224/28,192.168.127.240/29,192.168.127.248/31,192.168.127.250/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=firewall 9'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-allow

# Not written:
#   firewall 1: the source of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network; the destination of the rule is in zone wan1, and a rule of Google Cloud names no zone: give the networks behind wan1 with --zone-network
#   firewall 3: the source of the rule is in zone wan1, and a rule of Google Cloud names no zone: give the networks behind wan1 with --zone-network; the destination of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network
#   firewall 4: the source of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network; the destination of the rule is in zone wan2, and a rule of Google Cloud names no zone: give the networks behind wan2 with --zone-network
#   firewall 5: the source of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network
#   firewall 6: the source of the rule is in zone wan2, and a rule of Google Cloud names no zone: give the networks behind wan2 with --zone-network; the destination of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network
#   firewall 7: not converted: source MAC address 00:90:e8:00:00:01, which the model cannot match; not converted: mode MAC: the policy filters by source MAC address, which the model cannot match; the source of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zon
#   firewall 8: not converted: 'session-limit 50' is not converted; the source of the rule is in zone wan2, and a rule of Google Cloud names no zone: give the networks behind wan2 with --zone-network; the destination of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan 
#   firewall 10: the source of the rule is in zone wan2, and a rule of Google Cloud names no zone: give the networks behind wan2 with --zone-network; the destination of the rule is in zone lan, and a rule of Google Cloud names no zone: give the networks behind lan with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
